import { createHash } from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import { z } from 'zod';

import { CONFIG_DIR } from './constants.js';
import { getKeytar } from './keyring.js';

const service = 'mintlify-agent';
const fallbackFile = () => path.join(CONFIG_DIR, 'agent-credentials.json');

export const agentCredentialsSchema = z.object({
  registrationId: z.string().min(1),
  issuer: z.url(),
  assertion: z.string().min(1),
  claimToken: z.string().min(1),
  claimVerified: z.boolean().optional(),
  accessToken: z.string().min(1).optional(),
  accessTokenExpiresAt: z.number().optional(),
});

export type AgentCredentials = z.infer<typeof agentCredentialsSchema>;

function projectAccount(apiUrl: string, directory: string): string {
  return `project:${createHash('sha256')
    .update(JSON.stringify([new URL(apiUrl).origin, path.resolve(directory)]))
    .digest('hex')}`;
}

function registrationAccount(apiUrl: string, registrationId: string): string {
  return `${new URL(apiUrl).origin}:${registrationId}`;
}

async function readFallback(): Promise<Record<string, string>> {
  try {
    return z
      .record(z.string(), z.string())
      .parse(JSON.parse(await fs.readFile(fallbackFile(), 'utf-8')));
  } catch {
    return {};
  }
}

async function writeFallback(entries: Record<string, string>): Promise<void> {
  await fs.mkdir(CONFIG_DIR, { recursive: true });
  const temp = `${fallbackFile()}.${process.pid}.tmp`;
  await fs.writeFile(temp, JSON.stringify(entries, null, 2), { mode: 0o600 });
  await fs.chmod(temp, 0o600);
  await fs.rename(temp, fallbackFile());
}

async function getSecret(account: string): Promise<string | null> {
  let keyringError: unknown;
  try {
    const value = await (await getKeytar()).getPassword(service, account);
    if (value) return value;
  } catch (error) {
    keyringError = error;
  }
  const value = (await readFallback())[account];
  if (value) return value;
  if (keyringError) throw keyringError;
  return null;
}

async function setSecret(account: string, value: string): Promise<void> {
  try {
    await (await getKeytar()).setPassword(service, account, value);
  } catch {
    await writeFallback({ ...(await readFallback()), [account]: value });
    await getKeytar()
      .then((keytar) => keytar.deletePassword(service, account))
      .catch(() => {});
    return;
  }
  const { [account]: stale, ...rest } = await readFallback();
  if (stale) await writeFallback(rest).catch(() => {});
}

export async function loadAgentCredentials(
  apiUrl: string,
  directory: string
): Promise<AgentCredentials | null> {
  const registrationId = await getSecret(projectAccount(apiUrl, directory));
  if (!registrationId) return null;
  const value = await getSecret(registrationAccount(apiUrl, registrationId));
  if (!value)
    throw new Error('Saved agent credentials are missing. Use --new to create another site.');
  const credentials = agentCredentialsSchema.parse(JSON.parse(value));
  if (credentials.registrationId !== registrationId) {
    throw new Error('Saved agent credentials do not match this project.');
  }
  return credentials;
}

export async function saveAgentCredentials(
  apiUrl: string,
  directory: string,
  credentials: AgentCredentials
): Promise<void> {
  const value = agentCredentialsSchema.parse(credentials);
  await setSecret(registrationAccount(apiUrl, value.registrationId), JSON.stringify(value));
  await setSecret(projectAccount(apiUrl, directory), value.registrationId);
}
